@* Vertical navigation tabs for the settings dashboard *@

<nav class="nav nav-pills flex-column settings-sidebar">
    @foreach (var section in Sections)
    {
        <button class="nav-link text-start @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
            <span class="me-2">@GetIcon(section)</span>@section
        </button>
    }
</nav>

@code {
    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => ""
    };
}

@* Profile editing section *@

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Profile Settings</h4>

        <div class="row mb-4">
            <div class="col-md-3 text-center">
                <div class="border rounded p-3 mb-2">
                    @if (!string.IsNullOrEmpty(editModel.AvatarUrl))
                    {
                        <img src="@editModel.AvatarUrl" alt="Avatar" class="img-fluid rounded-circle" style="max-width: 120px; max-height: 120px;" />
                    }
                    else
                    {
                        <div class="bg-secondary text-white rounded-circle d-flex align-items-center justify-content-center mx-auto" style="width: 120px; height: 120px; font-size: 2rem;">
                            👤
                        </div>
                    }
                </div>
                <small class="text-muted text-break">@editModel.AvatarUrl</small>
            </div>
            <div class="col-md-9">
                <div class="mb-3">
                    <label class="form-label">Display Name</label>
                    <input type="text" class="form-control" @bind="editModel.DisplayName" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Email</label>
                    <input type="email" class="form-control" @bind="editModel.Email" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Avatar URL</label>
                    <input type="url" class="form-control" @bind="editModel.AvatarUrl" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Bio</label>
                    <textarea class="form-control" rows="3" @bind="editModel.Bio"></textarea>
                </div>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(successMessage))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @successMessage
                <button type="button" class="btn-close" @onclick="() => successMessage = null"></button>
            </div>
        }

        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                @if (isSaving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Save Changes
            </button>
            <button class="btn btn-outline-secondary" @onclick="Discard">Discard Changes</button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public UserProfile? Profile { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<UserProfile> OnSave { get; set; }

    private ProfileModel editModel = new();
    private bool isSaving;
    private string? successMessage;

    protected override void OnParametersSet()
    {
        if (Profile is not null && !hasInitialized)
        {
            ResetToProfile();
            hasInitialized = true;
        }
    }

    private bool hasInitialized;

    private void ResetToProfile()
    {
        if (Profile is null) return;
        editModel = new ProfileModel
        {
            DisplayName = Profile.DisplayName,
            Email = Profile.Email,
            AvatarUrl = Profile.AvatarUrl,
            Bio = Profile.Bio
        };
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        var updated = new UserProfile(editModel.DisplayName, editModel.Email, editModel.AvatarUrl, editModel.Bio);
        await OnSave.InvokeAsync(updated);
        isSaving = false;
        successMessage = "Profile saved successfully!";
    }

    private void Discard()
    {
        ResetToProfile();
        successMessage = null;
    }

    private class ProfileModel
    {
        public string DisplayName { get; set; } = "";
        public string Email { get; set; } = "";
        public string AvatarUrl { get; set; } = "";
        public string Bio { get; set; } = "";
    }
}

@* Notifications preferences section *@

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Notification Preferences</h4>

        <div class="mb-4">
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="emailNotif" @bind="emailNotifications" />
                <label class="form-check-label" for="emailNotif">Email Notifications</label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="pushNotif" @bind="pushNotifications" />
                <label class="form-check-label" for="pushNotif">Push Notifications</label>
            </div>
            <div class="form-check form-switch mb-3">
                <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="weeklyDigest" />
                <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
            </div>
        </div>

        <h5 class="mb-3">Muted Channels</h5>
        <div class="mb-4">
            @if (allChannels.Count == 0)
            {
                <p class="text-muted">No channels available.</p>
            }
            else
            {
                @foreach (var channel in allChannels)
                {
                    <div class="form-check mb-2">
                        <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                               checked="@mutedChannels.Contains(channel)"
                               @onchange="(e) => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                        <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                    </div>
                }
            }
        </div>

        @if (!string.IsNullOrEmpty(successMessage))
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @successMessage
                <button type="button" class="btn-close" @onclick="() => successMessage = null"></button>
            </div>
        }

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
            @if (isSaving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save Preferences
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public NotificationPrefs? Prefs { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<NotificationPrefs> OnSave { get; set; }

    [Parameter]
    public List<string> AllChannels { get; set; } = [];

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = [];
    private List<string> allChannels = [];
    private bool isSaving;
    private string? successMessage;
    private bool hasInitialized;

    protected override void OnParametersSet()
    {
        if (Prefs is not null && !hasInitialized)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = new HashSet<string>(Prefs.MutedChannels);
            hasInitialized = true;
        }

        allChannels = AllChannels.Count > 0 ? AllChannels : (Prefs?.MutedChannels ?? []);
    }

    private void ToggleChannel(string channel, bool isMuted)
    {
        if (isMuted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SaveAsync()
    {
        isSaving = true;
        var updated = new NotificationPrefs(emailNotifications, pushNotifications, weeklyDigest, mutedChannels.ToList());
        await OnSave.InvokeAsync(updated);
        isSaving = false;
        successMessage = "Preferences saved successfully!";
    }
}

@* Security settings section *@

<div class="card mb-4">
    <div class="card-body">
        <h4 class="card-title mb-4">Security Settings</h4>

        <!-- Change Password Panel -->
        <div class="mb-4">
            <button class="btn btn-outline-secondary w-100 text-start d-flex justify-content-between align-items-center"
                    @onclick="() => showPasswordPanel = !showPasswordPanel">
                <span><strong>Change Password</strong></span>
                <span>@(showPasswordPanel ? "▲" : "▼")</span>
            </button>

            @if (showPasswordPanel)
            {
                <div class="border rounded p-3 mt-2">
                    <div class="mb-3">
                        <label class="form-label">Current Password</label>
                        <input type="password" class="form-control" @bind="currentPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">New Password</label>
                        <input type="password" class="form-control" @bind="newPassword" />
                    </div>
                    <div class="mb-3">
                        <label class="form-label">Confirm New Password</label>
                        <input type="password" class="form-control" @bind="confirmPassword" />
                    </div>

                    @if (!string.IsNullOrEmpty(passwordError))
                    {
                        <div class="alert alert-danger">@passwordError</div>
                    }
                    @if (!string.IsNullOrEmpty(passwordSuccess))
                    {
                        <div class="alert alert-success">@passwordSuccess</div>
                    }

                    <button class="btn btn-warning" @onclick="ChangePasswordAsync" disabled="@isChangingPassword">
                        @if (isChangingPassword)
                        {
                            <span class="spinner-border spinner-border-sm me-1"></span>
                        }
                        Update Password
                    </button>
                </div>
            }
        </div>

        <!-- Two-Factor Authentication -->
        <div class="mb-4 p-3 border rounded">
            <div class="d-flex justify-content-between align-items-center">
                <div>
                    <h5 class="mb-1">Two-Factor Authentication</h5>
                    <span class="badge @(TwoFactorEnabled ? "bg-success" : "bg-secondary")">
                        @(TwoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" checked="@TwoFactorEnabled" disabled
                           title="Contact administrator to change 2FA settings" />
                </div>
            </div>
            @if (LastPasswordChange.HasValue)
            {
                <small class="text-muted mt-2 d-block">
                    Last password change: @LastPasswordChange.Value.ToString("MMMM dd, yyyy")
                </small>
            }
        </div>

        <!-- Active Sessions -->
        <div>
            <h5 class="mb-3">Active Sessions</h5>

            @if (Sessions.Count == 0)
            {
                <p class="text-muted">No active sessions.</p>
            }
            else
            {
                <div class="table-responsive">
                    <table class="table table-hover">
                        <thead>
                            <tr>
                                <th>Device</th>
                                <th>Location</th>
                                <th>Last Active</th>
                                <th></th>
                            </tr>
                        </thead>
                        <tbody>
                            @foreach (var session in Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session.Id != CurrentSessionId)
                                        {
                                            <button class="btn btn-sm btn-outline-danger"
                                                    @onclick="() => ConfirmRevoke(session)">
                                                Revoke
                                            </button>
                                        }
                                        else
                                        {
                                            <span class="badge bg-info">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        </tbody>
                    </table>
                </div>
            }
        </div>

        <!-- Revoke Confirmation Dialog -->
        @if (sessionToRevoke is not null)
        {
            <div class="modal d-block" tabindex="-1" style="background-color: rgba(0,0,0,0.5);">
                <div class="modal-dialog modal-dialog-centered">
                    <div class="modal-content">
                        <div class="modal-header">
                            <h5 class="modal-title">Revoke Session</h5>
                            <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                        </div>
                        <div class="modal-body">
                            <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke.Device</strong> from <strong>@sessionToRevoke.Location</strong>?</p>
                        </div>
                        <div class="modal-footer">
                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                            <button class="btn btn-danger" @onclick="RevokeAsync" disabled="@isRevoking">
