toolArgs.file_text:
@* Appearance settings section with live preview *@

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Appearance Settings</h4>

        <div class="row">
            <div class="col-md-7">
                <!-- Theme -->
                <div class="mb-4">
                    <h5>Theme</h5>
                    <div class="btn-group" role="group">
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <input type="radio" class="btn-check" name="theme" id="@($"theme-{theme}")"
                                   checked="@(selectedTheme == theme)"
                                   @onchange="() => selectedTheme = theme" />
                            <label class="btn btn-outline-primary" for="@($"theme-{theme}")">@theme</label>
                        }
                    </div>
                </div>

                <!-- Font Size -->
                <div class="mb-4">
                    <h5>Font Size</h5>
                    <div class="btn-group" role="group">
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <input type="radio" class="btn-check" name="fontSize" id="@($"size-{size}")"
                                   checked="@(selectedFontSize == size)"
                                   @onchange="() => selectedFontSize = size" />
                            <label class="btn btn-outline-secondary" for="@($"size-{size}")">@size</label>
                        }
                    </div>
                </div>

                <!-- Language -->
                <div class="mb-4">
                    <h5>Language</h5>
                    <select class="form-select" style="max-width: 250px;" @bind="selectedLanguage">
                        <option value="en">English</option>
                        <option value="es">Español</option>
                        <option value="fr">Français</option>
                        <option value="de">Deutsch</option>
                        <option value="ja">日本語</option>
                        <option value="zh">中文</option>
                    </select>
                </div>

                <!-- Compact Mode -->
                <div class="mb-4">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>

                @if (!string.IsNullOrEmpty(successMessage))
                {
                    <div class="alert alert-success alert-dismissible fade show" role="alert">
                        @successMessage
                        <button type="button" class="btn-close" @onclick="() => successMessage = null"></button>
                    </div>
                }

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@isSaving">
                    @if (isSaving)
                    {
                        <span class="spinner-border spinner-border-sm me-1"></span>
                    }
                    Save
                </button>
            </div>

            <!-- Live Preview -->
            <div class="col-md-5">
                <div class="border rounded p-3 @PreviewBackgroundClass" style="min-height: 200px;">
                    <h6 class="@PreviewTextClass" style="@PreviewFontStyle">Preview</h6>
                    <p class="@PreviewTextClass" style="@PreviewFontStyle">
                        This is how your content will look with the selected settings.
                    </p>
                    <div class="@PreviewTextClass" style="@PreviewFontStyle @PreviewSpacingStyle">
                        <span class="badge @PreviewBadgeClass">@selectedTheme Theme</span>
                        <span class="badge bg-secondary ms-1">@selectedFontSize</span>
                        <span class="badge bg-info ms-1">@GetLanguageLabel()</span>
                        @if (compactMode)
                        {
                            <span class="badge bg-warning text-dark ms-1">Compact</span>
                        }
                    </div>
                    <hr class="@PreviewTextClass" />
                    <ul style="@PreviewFontStyle @PreviewSpacingStyle" class="@PreviewTextClass">
                        <li>Navigation item 1</li>
                        <li>Navigation item 2</li>
                        <li>Navigation item 3</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public AppearanceSettings? Settings { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string selectedTheme = "Light";
    private string selectedFontSize = "Medium";
    private string selectedLanguage = "en";
    private bool compactMode;
    private bool isSaving;
    private string? successMessage;
    private bool hasInitialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !hasInitialized)
        {
            selectedTheme = Settings.Theme;
            selectedFontSize = Settings.FontSize;
            selectedLanguage = Settings.Language;
            compactMode = Settings.CompactMode;
            hasInitialized = true;
        }
    }

    private string PreviewBackgroundClass => selectedTheme switch
    {
        "Dark" => "bg-dark",
        _ => "bg-light"
    };

    private string PreviewTextClass => selectedTheme switch
    {
        "Dark" => "text-light",
        _ => "text-dark"
    };

    private string PreviewBadgeClass => selectedTheme switch
    {
        "Dark" => "bg-light text-dark",
        _ => "bg-dark text-light"
    };

    private string PreviewFontStyle => selectedFontSize switch
    {
        "Small" => "font-size: 0.8rem;",
        "Large" => "font-size: 1.2rem;",
        _ => "font-size: 1rem;"
    };

    private string PreviewSpacingStyle => compactMode ? "line-height: 1.2; margin-bottom: 0.25rem;" : "";

    private string GetLanguageLabel() => selectedLanguage switch
    {
        "es" => "Español",
        "fr" => "Français",
        "de" => "Deutsch",
        "ja" => "日本語",
        "zh" => "中文",
        _ => "English"
    };

    private async Task SaveAsync()
    {
        isSaving = true;
        var updated = new AppearanceSettings(selectedTheme, selectedFontSize, selectedLanguage, compactMode);
        await OnSave.InvokeAsync(updated);
        isSaving = false;
        successMessage = "Appearance settings saved!";
    }
}

