@page "/settings"
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="container-fluid py-4">
    <h2 class="mb-4">Settings</h2>

    <div class="row">
        <!-- Sidebar -->
        <div class="col-md-3 col-lg-2 mb-3">
            <SettingsSidebar ActiveSection="@activeSection" OnSectionChanged="SetSection" />
        </div>

        <!-- Main Content -->
        <div class="col-md-9 col-lg-10">
            @if (isLoading)
            {
                <div class="d-flex justify-content-center py-5">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else
            {
                @switch (activeSection)
                {
                    case "Profile":
                        <ProfileSection Profile="@profile" OnSave="SaveProfileAsync" />
                        break;
                    case "Notifications":
                        <NotificationsSection Prefs="@notificationPrefs"
                                              AllChannels="@allChannels"
                                              OnSave="SaveNotificationsAsync" />
                        break;
                    case "Security":
                        <SecuritySection TwoFactorEnabled="@(securitySettings?.TwoFactorEnabled ?? false)"
                                         LastPasswordChange="@securitySettings?.LastPasswordChange"
                                         Sessions="@(securitySettings?.Sessions ?? [])"
                                         CurrentSessionId="@currentSessionId"
                                         OnChangePassword="ChangePasswordAsync"
                                         OnRevokeSession="RevokeSessionAsync" />
                        break;
                    case "Appearance":
                        <AppearanceSection Settings="@appearanceSettings" OnSave="SaveAppearanceAsync" />
                        break;
                }
            }
        </div>
    </div>
</div>

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;

    private UserProfile? profile;
    private NotificationPrefs? notificationPrefs;
    private SecuritySettings? securitySettings;
    private AppearanceSettings? appearanceSettings;
    private List<string> allChannels = ["general", "announcements", "random", "engineering", "design", "marketing"];
    private string? currentSessionId;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllDataAsync();
        isLoading = false;
    }

    private async Task LoadAllDataAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        profile = await profileTask;
        notificationPrefs = await notifTask;
        securitySettings = await securityTask;
        appearanceSettings = await appearanceTask;

        // Assume the first session is the current one
        currentSessionId = securitySettings?.Sessions.FirstOrDefault()?.Id;
    }

    private void SetSection(string section)
    {
        activeSection = section;
    }

    private async Task SaveProfileAsync(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notificationPrefs = updated;
    }

    private async Task ChangePasswordAsync((string currentPassword, string newPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.currentPassword, args.newPassword);
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings updated)
    {
        await SettingsService.SaveAppearanceAsync(updated);
        appearanceSettings = updated;
    }
}

